_file_map = {

    "clients.baml": "// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview\r\nclient<llm> GroqRouter {\r\n  provider openai-generic\r\n  retry_policy Exponential\r\n  options {\r\n    base_url \"https://api.groq.com/openai/v1\"\r\n    api_key env.GROQ_API_KEY\r\n    model \"openai/gpt-oss-120b\"\r\n  }\r\n}\r\n\r\n// https://docs.boundaryml.com/docs/snippets/clients/retry\r\nretry_policy Constant {\r\n  max_retries 3\r\n  strategy {\r\n    type constant_delay\r\n    delay_ms 200\r\n  }\r\n}\r\n\r\nretry_policy Exponential {\r\n  max_retries 2\r\n  strategy {\r\n    type exponential_backoff\r\n    delay_ms 300\r\n    multiplier 1.5\r\n    max_delay_ms 10000\r\n  }\r\n}\r\n",
    "exp_orchestrator.baml": "class ExperimentWithFilename {\r\n  experiment map<string, string> @description(\"single experiment with key-value pairs\")\r\n  filename string @description(\"filename for this specific experiment without extension\")\r\n}\r\n\r\nclass ExpOrchestratorOutput {\r\n  number_of_scans int @description(\"total number of scans to be performed\")\r\n  experiments ExperimentWithFilename[] @description(\"list of experiments with filenames\")\r\n  response string @description(\"natural language response summarizing the experiments\")\r\n}\r\n\r\nfunction ExpOrchestrator(\r\n  user_message: string, \r\n  conversation_history: ConversationMessage[]?)\r\n-> ExpOrchestratorOutput {\r\n  client GroqRouter\r\n  prompt #\"\r\nYou are a lab automation agent that converts natural language into structured JSON experiments with individual filenames.\r\n\r\nEXPERIMENT PARSING RULES:\r\n1. Split on: commas, \"and\", \"then\", \"next\", \"after\"\r\n2. Parameters persist unless changed\r\n3. Infer parameter keys: \"20x20\"→scan_dimensions, \"gaussian\"→scan_type, \"1kHz\"→frequency, etc.\r\n4. Use snake_case; omit null values\r\n5. EXPAND RANGES: \"10 to 30\"→[10,20,30], \"1000 to 1200Hz\"→[1000,1050,1100,1150,1200]\r\n6. CREATE CARTESIAN PRODUCT: When multiple parameters have ranges, create separate experiments for ALL combinations\r\n   - Example: 3 areas × 5 frequencies = 15 experiments\r\n7. Each experiment object must have SINGLE values, not arrays\r\n\r\nFILENAME GENERATION RULES (Applied to EACH experiment):\r\n- Format: {pulse_mode}_{key_parameters_with_values}\r\n- Use underscores to separate components\r\n- Include ONLY the specific parameter values for THIS experiment\r\n- Prioritize the most distinctive experimental parameters\r\n- Keep total length under 50 characters\r\n- Use standard abbreviations (amp=amplitude, freq=frequency, atten=attenuation, etc.)\r\n- For scan dimensions, use format: {xl}x{yl} (e.g., 20x20)\r\n- DON'T include \"scan\" in filename\r\n- Each filename must be UNIQUE and reflect the specific parameter combination\r\n\r\nEXAMPLES:\r\n\r\nInput: \"scan 10x10 and 20x20 gaussian at 1kHz and 2kHz\"\r\nOutput:\r\n{\r\n  \"number_of_scans\": 4,\r\n  \"experiments\": [\r\n    {\r\n      \"experiment\": {\"scan_dimensions\": \"10x10\", \"scan_type\": \"gaussian\", \"frequency\": \"1000Hz\"},\r\n      \"filename\": \"gaussian_10x10_freq1000\"\r\n    },\r\n    {\r\n      \"experiment\": {\"scan_dimensions\": \"10x10\", \"scan_type\": \"gaussian\", \"frequency\": \"2000Hz\"},\r\n      \"filename\": \"gaussian_10x10_freq2000\"\r\n    },\r\n    {\r\n      \"experiment\": {\"scan_dimensions\": \"20x20\", \"scan_type\": \"gaussian\", \"frequency\": \"1000Hz\"},\r\n      \"filename\": \"gaussian_20x20_freq1000\"\r\n    },\r\n    {\r\n      \"experiment\": {\"scan_dimensions\": \"20x20\", \"scan_type\": \"gaussian\", \"frequency\": \"2000Hz\"},\r\n      \"filename\": \"gaussian_20x20_freq2000\"\r\n    }\r\n  ],\r\n  \"response\": \"Created 4 gaussian scan experiments with dimensions 10x10 and 20x20 at frequencies 1kHz and 2kHz.\"\r\n}\r\n\r\nInput: \"gaussian 50x50 at 5kHz amplitude 2.1V\"\r\nOutput:\r\n{\r\n  \"number_of_scans\": 1,\r\n  \"experiments\": [\r\n    {\r\n      \"experiment\": {\"scan_type\": \"gaussian\", \"scan_dimensions\": \"50x50\", \"frequency\": \"5000Hz\", \"amplitude\": \"2.1V\"},\r\n      \"filename\": \"gaussian_50x50_freq5000_amp2.1V\"\r\n    }\r\n  ],\r\n  \"response\": \"Created 1 gaussian scan experiment at 50x50, 5kHz, 2.1V amplitude.\"\r\n}\r\n\r\n{% if conversation_history %}\r\nRecent conversation context:\r\n<conversation_history>\r\n{% for message in conversation_history %}\r\n{{ message.role }}: {{ message.content }}\r\n{% endfor %}\r\n</conversation_history>\r\n{% endif %}\r\n\r\n<user_message>\r\n{{ user_message }}\r\n</user_message>\r\n\r\n{{ ctx.output_format }}\r\n\"#\r\n}\r\n\r\ntest TestOrchestrator {\r\n  functions [ExpOrchestrator]\r\n  args {\r\n    user_message #\"\r\n# EXPERIMENTAL PLAN: VAE Data Collection for Early Corrosion Detection\r\n\r\n## GOAL\r\nAcquire a comprehensive dataset of Pulsed Eddy Current (PEC) signals from both pristine and early-stage corroded Al2024 samples to train and validate a Variational Autoencoder (VAE) for anomaly detection.\r\n\r\n## SAMPLES\r\n- **Pristine Al2024:** 10 samples (100mm x 100mm x 5mm, typical aerospace alloy thickness). These will serve as the \"healthy\" baseline.\r\n- **Early-Stage Corroded Al2024:** 20 samples (100mm x 100mm x 5mm). These samples will have artificially introduced, controlled corrosion defects of varying severities and depths (e.g., 5%, 10%, 15% material loss localized to distinct areas, depth 0.1mm - 0.5mm) to represent early-stage degradation. Corroded areas should be well-characterized prior to PEC scanning using gravimetric analysis or profilometry.\r\n\r\n## SCAN APPROACH\r\n- **Constant Parameters:** All scans will use a Gaussian waveform with `Gauss amp = 2.1V`, `Gauss freq = 1000 Hz`, `Gauss Nor.Band = 0.5`, `Gauss atten = 6 dB`. Lift-off will be fixed at 1.0 mm for all scans.\r\n- **Varying Parameters:** To introduce controlled variability representative of real-world scenarios, a subset of healthy and corroded samples will be scanned with slight variations in:\r\n    - **StepX/StepY:** 1mm, 2mm (to assess resolution impact)\r\n    - **Speed:** 1 mm/s, 2 mm/s (to assess scan speed impact on signal quality/noise)\r\n    - **Probe Orientation:** Introduce 0, 90, 180, 270 degree rotations for 2 healthy and 4 corroded samples to simulate deployment variability. This simulates real-world usage conditions where precise probe alignment might not always be achievable.\r\n\r\n## PROCEDURE\r\n1.  **Baseline Healthy Data Collection:**\r\n    *   Place a pristine Al2024 sample on the scanning platform.\r\n    *   Set `Lift-off` to 1.0 mm.\r\n    *   Execute a full 100mm x 100mm scan at `StepX = 1mm`, `StepY = 1mm`, `Speed = 2 mm/s`.\r\n    *   Repeat for all 10 pristine samples, varying `StepX/StepY` and `Speed` as specified in \"Varying Parameters\" for designated samples.\r\n    *   For the 2 designated samples, re-scan with probe rotations (0, 90, 180, 270 degrees).\r\n2.  **Early-Stage Corroded Data Collection:**\r\n    *   Place a corroded Al2024 sample on the scanning platform, ensuring known corroded areas are within the scan region.\r\n    *   Set `Lift-off` to 1.0 mm.\r\n    *   Execute a full 100mm x 100mm scan at `StepX = 1mm`, `StepY = 1mm`, `Speed = 2 mm/s`.\r\n    *   Repeat for all 20 corroded samples, varying `StepX/StepY` and `Speed` as specified in \"Varying Parameters\" for designated samples.\r\n    *   For the 4 designated samples, re-scan with probe rotations (0, 90, 180, 270 degrees).\r\n3.  **Data Labeling and Annotation:**\r\n    *   For each corroded sample scan, precisely label the spatial coordinates (X, Y) corresponding to the known corroded areas, along with their estimated severity (e.g., % material loss) and depth. This ground truth is crucial for training and validation.\r\n\r\n## WATCH FOR\r\n-   **Lift-off consistency:** Manual lift-off verification before each scan, especially for different samples, to ensure the 1.0mm setting is maintained.\r\n-   **Sensor Drift/Noise:** Periodically scan a reference pristine sample (e.g., every 5 samples) to monitor for sensor drift or increased noise floor. Re-run scans if significant deviation from initial reference is observed.\r\n-   **Sample Placement:** Ensure consistent sample orientation and placement to enable accurate defect mapping.\r\n-   **Robotic Arm Stability:** Monitor for any vibrations or jerky movements that could introduce noise into the signal.\r\n\r\n## SUCCESS CHECK\r\n-   A minimum of 500 individual PEC time-domain signals (500 samples each) acquired per 100x100mm scan area (~10,000 data points per scan).\r\n-   Consistent signal characteristics for healthy samples, with observable and distinct deviations in corroded areas.\r\n-   Accurate spatial mapping of known corrosion defects within the acquired data for at least 80% of corroded samples.\r\n-   Variation in scanning parameters (StepX/Y, Speed, Probe Orientation) introduces slight but manageable signal variance, allowing the VAE to learn robust feature representations.\r\n    \"#\r\n  }\r\n}\r\n\r\n",
    "exp_planner.baml": "function ExpPlanner(\r\n    user_message: string,\r\n    filename: string?\r\n) -> (SetNumericControlTool | SelectComboBoxTool | SelectTabTool | RunOpenViTool | ConnectToViTool | HandleSaveDialogTool | PressButtonTool | SetButtonStateTool)[] {\r\n  client GroqRouter\r\n  prompt #\"\r\nYou are a LabVIEW experiment control agent. Interpret user requests and generate sequences of parameter-setting functions for LabVIEW operations.\r\n\r\nCORE INSTRUCTIONS\r\n\r\n1. Analyze the user request to determine operation type:\r\n   - Scan operation: Full workflow with pulse mode, motion parameters, and data acquisition\r\n   - Movement operation: Directional movement (right/left/forward/backward)\r\n   - Parameter setting: Setting individual controls without running experiments\r\n   - System control: Starting/stopping/resetting operations\r\n\r\n2. Generate minimal sequences - only include necessary steps for the requested operation\r\n3. Use exact control names as specified in the constraints\r\n4. Configure only mentioned parameters - unspecified parameters use defaults\r\n\r\nAVAILABLE FUNCTIONS\r\n\r\nrun_open_vi(run_vi) - Open LabVIEW application\r\nconnect_to_vi(vi_path) - Connect to VI file\r\nhandle_save_dialog(save_directory, filename) - Handle save operations\r\npress_button(button_name) - Press UI button\r\nset_button_state(button_name, state) - Set button state (True/False)\r\nselect_tab(control_name, index) - Switch tabs/modes\r\nselect_combo_box(control_name, value) - Set dropdown selections\r\nset_numeric_control(control_name, value) - Set numeric values\r\n\r\nSYSTEM CONFIGURATION\r\n\r\nPULSE MODES (Tab Control 4):\r\nBasic (0): \"Basic Type\"(Sine/Triangle/Square/Sawtooth Wave), \"Duty cycle %\"(50), \"Basic freq (Hz)\"(200), \"Basic amp\"(1.13)\r\nGaussian (1): \"Gauss amp\"(2.1), \"Gauss atten (dB)\"(6), \"Gauss freq (Hz)\"(1000), \"Gauss Nor.Band\"(0.5)\r\nChirp (2): \"Chirp amp\"(160), \"Chirp f1\"(500), \"Chirp f2\"(1500)\r\n\r\nMOTION PARAMETERS: \"Speed (mm/s)\"(2), \"xl\"(100), \"yl\"(100), \"StepX\"(1), \"StepY\"(1)\r\n\r\nDEFAULTS: Values in parentheses are defaults. Only set parameters explicitly mentioned by user.\r\n\r\nOPERATION TYPES AND WORKFLOWS\r\n\r\n1. SCAN OPERATION\r\nTriggers: User mentions \"scan\", provides scan dimensions, or specifies pulse parameters with motion\r\n\r\nFull Workflow:\r\n1. run_open_vi(False)\r\n2. connect_to_vi(\"file_vi.vi\")\r\n3. select_tab(\"Tab Control 2\", 1) - Switch to scan mode\r\n4. select_tab(\"Tab Control 4\", [mode_index]) - Select pulse mode (0/1/2)\r\n5. [If Basic mode] select_combo_box(\"Basic Type\", waveform_type)\r\n6. Configure pulse parameters with set_numeric_control()\r\n7. Configure motion parameters with set_numeric_control()\r\n8. run_open_vi(True)\r\n9. handle_save_dialog(\"DIRECTORY\", \"{{ filename }}\")\r\n10. connect_to_vi(\"file_vi.vi\")\r\n11. set_button_state(\"sethome\", True) - REQUIRED before scan\r\n12. set_button_state(\"Scan\", True)\r\n\r\nMode Selection:\r\nUser mentions \"gaussian\" -> [mode_index] = 1\r\nUser mentions \"chirp\" -> [mode_index] = 2\r\nUser mentions \"sine/triangle/square/sawtooth\" OR default -> [mode_index] = 0\r\n\r\n2. MOVEMENT OPERATION\r\nTriggers: User mentions \"move\", \"go right/left/forward/backward\"\r\n\r\nWorkflow:\r\n1. connect_to_vi(\"file_vi.vi\")\r\n2. set_numeric_control(\"Move Dis(mm)\", distance_value) - Set distance to move\r\n3. set_button_state(direction_button, True) - direction_button is \"right\", \"left\", \"forward\", or \"backward\"\r\n\r\nDirection Mapping:\r\n\"right\" or \"east\" -> button \"right\"\r\n\"left\" or \"west\" -> button \"left\"\r\n\"forward\" or \"north\" or \"up\" -> button \"forward\"\r\n\"backward\" or \"south\" or \"down\" -> button \"backward\"\r\n\r\n3. PARAMETER SETTING\r\nTriggers: User says \"set [parameter]\", \"change [value]\", \"configure [setting]\" WITHOUT scanning\r\n\r\nWorkflow:\r\n1. connect_to_vi(\"file_vi.vi\")\r\n2. set_numeric_control() or select_combo_box() - Configure requested parameters only\r\n\r\n4. SYSTEM CONTROL\r\nTriggers: \"stop\", \"reset\", \"home\", \"initialize\"\r\n\r\nWorkflow:\r\n1. connect_to_vi(\"file_vi.vi\")\r\n2. set_button_state() or press_button() - Execute control action\r\n\r\nCommon Actions:\r\nGo Home: set_button_state(\"gohome\", True)\r\nSet Current Position as Home: set_button_state(\"sethome\", True)\r\nStop: set_button_state(\"Stop\", True)\r\n\r\nDECISION LOGIC\r\n\r\nDetermine operation type by keywords:\r\nContains \"scan\" OR (pulse_mode + dimensions) -> SCAN OPERATION\r\nContains \"move\" OR \"right\" OR \"left\" OR \"forward\" OR \"backward\" -> MOVEMENT OPERATION\r\nContains \"set\" OR \"change\" (parameter only, no scan) -> PARAMETER SETTING\r\nContains \"stop\" OR \"home\" -> SYSTEM CONTROL\r\n\r\nUSER REQUEST\r\n\r\n{{ user_message }}\r\n\r\nIMPORTANT NOTES\r\n\r\nFilename for save operations: {{ filename }}\r\nOnly configure parameters explicitly mentioned by user\r\nUse exact control names as specified above\r\nFollow the complete workflow sequence for scan operations\r\nUse minimal sequences for other operations\r\nMovement is directional only - use right/left/forward/backward buttons with specified distance\r\n\r\n{{ ctx.output_format }}\r\n\"#\r\n}\r\n\r\n// Test Cases\r\ntest TestScanOperation {\r\n  functions [ExpPlanner]\r\n  args {\r\n    user_message \"scan for me 20x20 using gaussian\"\r\n    filename \"gaussian_20x20_freq1000\"\r\n  }\r\n}\r\n\r\ntest TestMovementOperation {\r\n  functions [ExpPlanner]\r\n  args {\r\n    user_message \"move to right by 10mm\"\r\n    filename \"movement_log\"\r\n  }\r\n}\r\n\r\ntest TestMovementOperation2 {\r\n  functions [ExpPlanner]\r\n  args {\r\n    user_message \"I am at coordinate (0, 0), moving to (5, 5)\"\r\n    filename \"movement_log\"\r\n  }\r\n}\r\n\r\ntest TestParameterSetting {\r\n  functions [ExpPlanner]\r\n  args {\r\n    user_message \"set speed to 5 mm/s\"\r\n    filename \"config_update\"\r\n  }\r\n}\r\n\r\ntest TestSystemControl {\r\n  functions [ExpPlanner]\r\n  args {\r\n    user_message \"go to home position\"\r\n    filename \"home_operation\"\r\n  }\r\n}\r\n\r\ntest TestChirpScan {\r\n  functions [ExpPlanner]\r\n  args {\r\n    user_message \"perform 15x15 chirp scan with f1=300Hz and f2=2000Hz\"\r\n    filename \"chirp_15x15_300_2000\"\r\n  }\r\n}\r\n\r\ntest TestBasicSineScan {\r\n  functions [ExpPlanner]\r\n  args {\r\n    user_message \"scan 10x10 using sine wave at 500Hz\"\r\n    filename \"sine_10x10_500hz\"\r\n  }\r\n}",
    "exp_router.baml": "enum ExpAction {\r\n    BASIC_CONTROL\r\n    SINGLE_SCAN\r\n    MULTIPLE_SCAN\r\n    ASK_CLARIFICATION\r\n}\r\n\r\nclass ExpRouterOutput {\r\n  action ExpAction\r\n  response string? @description(\"message to show user, only for ASK_CLARIFICATION\")\r\n}\r\n\r\nfunction ExpRouter(\r\n  user_message: string,\r\n  conversation_history: ConversationMessage[]?\r\n) -> ExpRouterOutput {\r\n  client GroqRouter\r\n  prompt #\"\r\nYou are a coordinator for a PECT lab automation system. Analyze the user's message and categorize the intent.\r\n\r\nROUTING DECISION LOGIC\r\n\r\nOPTION 1: BASIC_CONTROL\r\nUse when user wants direct hardware control or simple single actions:\r\n- Movement commands: \"move to right\", \"move left\", \"go to position X\", \"shift up/down\"\r\n- Button/actuator control: \"set button stop\", \"press button\", \"activate relay\", \"turn on/off\"\r\n- Status queries: \"get position\", \"check status\", \"read sensor\"\r\n- Simple parameter changes: \"set temperature to 37\", \"adjust speed\"\r\n\r\nKeywords: move, set, press, activate, turn, go, shift, position, button, stop, start\r\n\r\n→ action=\"BASIC_CONTROL\"\r\n→ response: null (system will execute command directly)\r\n\r\nOPTION 2: SINGLE_SCAN\r\nUse when user requests ONE scanning operation with clear parameters:\r\n- Explicit single scan: \"scan 20x20\", \"do a scan\", \"perform one scan\"\r\n- Scan with method specified: \"scan 20x20 with gaussian\", \"run a raster scan 10x10\"\r\n- One-time measurement: \"measure this area 15x15\", \"take a scan of 5x5 grid\"\r\n\r\nMust have EITHER:\r\n- Grid dimensions (e.g., \"20x20\", \"10x10\")\r\n- OR scan method (e.g., \"gaussian\", \"raster\", \"spiral\")\r\n- OR both\r\n\r\nKeywords: scan, measure, take, one scan, single scan, do a scan\r\n\r\n→ action=\"SINGLE_SCAN\"\r\n→ response: null (system will execute scan)\r\n\r\nOPTION 3: MULTIPLE_SCAN\r\nUse when user wants to create/load/execute a complex experimental plan with multiple scans:\r\n- Explicit multiple scans: \"run 5 scans\", \"do multiple scans\", \"scan 3 times\"\r\n- Experimental plan requests: \"create experiment\", \"generate experiment plan\", \"design study\"\r\n- Loading saved plans: \"load plan\", \"use saved plan\", \"resume experiment\"\r\n- Sequential operations: \"scan area A then B\", \"do scan series\"\r\n- Plans with conditions: \"scan until X\", \"repeat scan every hour\"\r\n\r\nMust involve EITHER:\r\n- Multiple scan operations\r\n- OR experimental workflow/plan\r\n- OR saved plan reference\r\n- OR conditional/repeated scanning\r\n\r\nKeywords: multiple, experiment, plan, create, generate, load, series, repeat, schedule\r\n\r\n→ action=\"MULTIPLE_SCAN\"\r\n→ response: null (system will invoke plan creation/loading agent)\r\n\r\nOPTION 4: ASK_CLARIFICATION\r\nUse when:\r\n- Simple greeting without context: \"hi\", \"hello\", \"hey\"\r\n- Ambiguous intent: \"do something\", \"help me\", \"what can you do\"\r\n- Incomplete scan specification: \"scan for me\" (no dimensions or method)\r\n- Missing critical parameters: \"move\" (no direction), \"scan\" (no details)\r\n- Unclear scope: \"test this sample\" (no methodology)\r\n\r\n→ action=\"ASK_CLARIFICATION\"\r\n→ response: REQUIRED - Ask specific question to clarify user intent:\r\n  - For greetings: \"Hi! Would you like to: (1) Control the system directly, (2) Run a single scan, or (3) Create/load an experimental plan?\"\r\n  - For incomplete scans: \"I can help you scan. Please specify: grid dimensions (e.g., 20x20) and/or scan method (e.g., gaussian, raster)\"\r\n  - For vague requests: Ask for the specific missing information\r\n\r\nDECISION TREE\r\n1. Is it a direct hardware command? → BASIC_CONTROL\r\n2. Is it a single, one-time scan with parameters? → SINGLE_SCAN\r\n3. Does it involve multiple scans or experimental planning? → MULTIPLE_SCAN\r\n4. Is the intent unclear or information missing? → ASK_CLARIFICATION\r\n\r\n{% if conversation_history %}\r\nCONVERSATION HISTORY:\r\n{% for message in conversation_history %}\r\n{{ message.role }}: {{ message.content }}\r\n{% endfor %}\r\n{% endif %}\r\n\r\nUSER MESSAGE:\r\n{{ user_message }}\r\n\r\n{{ ctx.output_format }}\r\n\"#\r\n}\r\n\r\n\r\ntest TestExpRouter {\r\n  functions [ExpRouter]\r\n  args {\r\n    user_message \"scan for me 20x20 using gaussian\"\r\n  }\r\n}\r\n\r\ntest TestExpRouter2 {\r\n  functions [ExpRouter]\r\n  args {\r\n    user_message \"move to right by 10mm\"\r\n  }\r\n}\r\n\r\ntest TestExpRouter3 {\r\n  functions [ExpRouter]\r\n  args {\r\n    user_message \"I am at coordinate (0, 0), moving to (5, 5)\"\r\n  }\r\n}\r\n\r\ntest TestExpRouter4 {\r\n  functions [ExpRouter]\r\n  args {\r\n    user_message \"set speed to 5 mm/s\"\r\n  }\r\n}\r\n\r\ntest TestExpRouter5 {\r\n  functions [ExpRouter]\r\n  args {\r\n    user_message \"who are you?\"\r\n  }\r\n}",
    "exp_tools.baml": "// list of tools to set params for experiment\r\nclass SetNumericControlTool {\r\n    tool_name \"set_numeric_control\" @description(\"Use this tool to set the value of a numeric control on the VI front panel\")\r\n    control_name string @description(\"Name of the numeric control to set\")\r\n    value float @description(\"Value to set the numeric control to\")\r\n}\r\n\r\nclass SelectComboBoxTool {\r\n    tool_name \"select_combo_box\" @description(\"Use this tool to select an item from a combo box control on the VI front panel\")\r\n    combo_box_name string @description(\"Name of the combo box control\")\r\n    item string @description(\"Item to select from the combo box\")\r\n}\r\n\r\nclass SelectTabTool {\r\n    tool_name \"select_tab\" @description(\"Use this tool to select a tab in a tab control on the VI front panel\")\r\n    tab_control_name string @description(\"Name of the tab control\")\r\n    index int @description(\"Index of the tab to select (0-based)\")\r\n}\r\n\r\n// list of tools to interact with Labview (not dynamic)\r\nclass RunOpenViTool {\r\n    tool_name \"run_open_vi\" @description(\"Use this tool to open and run a LabVIEW VI\")\r\n    run_vi bool @description(\"Set to true to run the VI after opening it\")\r\n}\r\n\r\nclass ConnectToViTool {\r\n    tool_name \"connect_to_vi\" @description(\"Use this tool to connect to a running LabVIEW VI\")\r\n    vi_path string @description(\"Path to the LabVIEW VI to connect to\")\r\n}\r\n\r\nclass HandleSaveDialogTool {\r\n    tool_name \"handle_save_dialog\" @description(\"Use this tool to handle the save dialog in LabVIEW\")\r\n    save_directory string @description(\"Directory to save the file to\")\r\n    file_name string @description(\"Name of the file to save\")\r\n}\r\n\r\nclass PressButtonTool {\r\n    tool_name \"press_button\" @description(\"Use this tool to press a button on the VI front panel\")\r\n    button_name string @description(\"Name of the button to press\")\r\n}\r\n\r\nclass SetButtonStateTool {\r\n    tool_name \"set_button_state\" @description(\"Use this tool to set the state of a button on the VI front panel\")\r\n    button_name string @description(\"Name of the button to set\")\r\n    state bool @description(\"State to set the button to (true for pressed, false for unpressed)\")\r\n}\r\n",
    "generators.baml": "// This helps use auto generate libraries you can use in the language of\r\n// your choice. You can have multiple generators if you use multiple languages.\r\n// Just ensure that the output_dir is different for each generator.\r\ngenerator target {\r\n    // Valid values: \"python/pydantic\", \"typescript\", \"ruby/sorbet\", \"rest/openapi\"\r\n    output_type \"python/pydantic\"\r\n\r\n    // Where the generated code will be saved (relative to baml_src/)\r\n    output_dir \"../\"\r\n\r\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\r\n    // The BAML VSCode extension version should also match this version.\r\n    version \"0.214.0\"\r\n\r\n    // Valid values: \"sync\", \"async\"\r\n    // This controls what `b.FunctionName()` will be (sync or async).\r\n    default_client_mode sync\r\n}\r\n",
    "idea_brainstormer.baml": "function Brainstormer(\r\n    user_message: string,\r\n    relevant_context: string?,\r\n    system_specs: string?,\r\n    experiment_plan: string?,\r\n    data_science_plan: string?,\r\n    existing_idea: string?\r\n) -> string {\r\n    client GroqRouter\r\n    prompt #\"\r\nYou are GPECT Assistant, expert R&D partner for Pulsed Eddy Current Testing.\r\nGenerate testable hypotheses and plans with quantitative guidance. Be direct, technical, never fabricate.\r\n\r\nRESPONSE MODES\r\n\r\nMODE 1: GENERATE IDEA\r\n1-3 ideas, 2-4 sentences each:\r\n- Core insight/what-if\r\n- Why it matters  \r\n- Key test needed\r\n\r\nExample: \"What if we used multi-frequency sweeps to create a 'depth profile' of coating thickness? Different frequencies penetrate to different depths, enabling thickness variation mapping. Test: calibrate frequency-to-depth mapping on samples with known gradients.\"\r\n\r\nEnd with: \"Develop any into a full plan?\"\r\n\r\n---\r\n\r\nMODE 2: DETAIL SPECIFIC IDEA\r\nIDEA [N]: [Title]\r\nCORE: [What you're testing - 1 sentence]\r\nAPPROACH: [3 bullet steps]\r\nMEASURE: [Specific outputs]\r\nRISK: [Main challenge]\r\n\r\nEnd with: \"Save this idea?\"\r\n\r\n---\r\n\r\nMODE 3: EXPERIMENTAL PLAN\r\nEXPERIMENT COUNT: [N runs]\r\nCalculation: [show multiplication, e.g., \"4 frequencies × 3 samples = 12 runs\"]\r\n\r\nGOAL: [One sentence - what you're measuring]\r\n\r\nDESIGN:\r\n- Type: [Full factorial / Parameter sweep / Pair comparison / Single-variable / etc.]\r\n- Keep small: Aim for 5-20 total runs unless justified\r\n\r\nSAMPLES:\r\n[N] × [material type] with [specific defect/variation]\r\n\r\nPARAMETERS:\r\nFixed:\r\n- `param_name`: [value] — [why fixed]\r\n\r\nVariable (swept/tested):\r\n- `param_name`: [start] to [end], [N] steps — [what you're testing]\r\n- `param_name`: [option1, option2, option3] — [what you're comparing]\r\n\r\nPROCEDURE:\r\n1. Baseline: [specific action]\r\n2. Data collection: [loop structure or sequence]\r\n3. Validation: [quality check]\r\n\r\nSUCCESS CRITERIA:\r\n- [Metric 1]: [target value or range]\r\n- [Metric 2]: [target value or range]\r\n\r\nEnd with: \"Save experiment plan?\"\r\n\r\n---\r\n\r\nMODE 4: DATA SCIENCE PLAN\r\nGOAL: [One sentence - what you're predicting/classifying]\r\n\r\nDATA:\r\n- Filter: [method, cutoff values]\r\n- Normalize: [method]\r\n- Quality check: [criteria]\r\n\r\nFEATURES: [3-5 signal characteristics with brief reason each]\r\n\r\nMODEL:\r\n- Algorithm: [name] — [why this one]\r\n- Split: [ratio] train/test\r\n- Validation: [k]-fold cross-validation\r\n- Tune: [2-4 key hyperparameters with ranges]\r\n\r\nMETRICS:\r\nPrimary: [metric] > [target]\r\nSecondary: [metric1], [metric2]\r\n\r\nOUTPUT: [Model format, visualization types]\r\n\r\nEnd with: \"Save data science plan?\"\r\n\r\n---\r\n\r\nMODE 5: USER APPROVES → Confirm, ask \"What's next?\"\r\n\r\nMODE 6: USER REVISES → Ask what to modify\r\n\r\n---\r\n\r\nCONTEXT\r\n{% if system_specs %}\r\n<system_specs>\r\n{{ system_specs }}\r\n</system_specs>\r\n{% endif %}\r\n\r\n{% if experiment_plan %}\r\n<experiment_plan>\r\n{{ experiment_plan }}\r\n</experiment_plan>\r\n{% endif %}\r\n\r\n{% if data_science_plan %}\r\n<data_science_plan>\r\n{{ data_science_plan }}\r\n</data_science_plan>\r\n{% endif %}\r\n\r\n{% if existing_idea %}\r\n<idea>\r\n{{ existing_idea }}\r\n</idea>\r\n{% endif %}\r\n\r\n{% if relevant_context %}\r\n<relevant_context>\r\n{{ relevant_context }}\r\n</relevant_context>\r\n{% endif %}\r\n\r\nUSER MESSAGE\r\n{{ user_message }}\r\n\"#\r\n}",
    "idea_file_manager.baml": "class SearchReplaceBlock {\r\n  search string @description(\"Exact code/text to find - must match precisely including whitespace\")\r\n  replace string @description(\"Replacement code/text with same indentation and formatting\")\r\n  language string @description(\"Programming language or 'markdown' for .md files\")\r\n}\r\n\r\nclass FileChange {\r\n  file_path string @description(\"Exact path from available_files list\")\r\n  blocks SearchReplaceBlock[] @description(\"Search/replace operations for this file\")\r\n}\r\n\r\nclass SearchReplaceTool {\r\n  files_to_change FileChange[] @description(\"Files to modify with their changes\")\r\n  reasoning string @description(\"Why these changes are being made\")\r\n}\r\n\r\nfunction FileManager(\r\n    content_to_save: string,\r\n    target_files: string[],\r\n    operation_type: string? @description(\"'save_new', 'update_existing', or 'auto'\")\r\n) -> SearchReplaceTool {\r\n    client GroqRouter\r\n    prompt #\"\r\nYou are a File Manager for PECT Assistant. Your job is to save or update content to files using search/replace operations.\r\n\r\nOPERATION RULES:\r\n\r\n1. FOR NEW CONTENT OR EMPTY FILES:\r\n   - Use search=\"\" (empty string)\r\n   - Put the full content in replace field\r\n   - Set language to 'markdown' for .md files, or appropriate language for code\r\n\r\n2. FOR UPDATING EXISTING FILES:\r\n   - search must contain EXACT text from the file to be replaced\r\n   - search must match precisely including all whitespace and formatting\r\n   - replace contains the new content with same indentation\r\n   - If updating multiple sections, create multiple SearchReplaceBlock entries\r\n\r\n3. FILE PATH REQUIREMENTS:\r\n   - Use EXACT paths from available_files list\r\n   - Only use paths that exist in target_files\r\n\r\n4. REASONING FIELD:\r\n   - Clearly explain what content is being saved/updated\r\n   - Mention which files are affected\r\n   - Describe the purpose of the changes\r\n\r\nTARGET FILES TO MODIFY:\r\n{% for file in target_files %}\r\n- {{ file }}\r\n{% endfor %}\r\n\r\nCONTENT TO SAVE:\r\n{{ content_to_save }}\r\n\r\n{% if operation_type %}\r\nOPERATION TYPE: {{ operation_type }}\r\n{% endif %}\r\n\r\nINSTRUCTIONS:\r\n- Create a SearchReplaceBlock for each file in target_files\r\n- If operation_type is 'save_new' or files are empty, use search=\"\"\r\n- If operation_type is 'update_existing', ensure search matches existing content exactly\r\n- Set appropriate language for each file\r\n- Provide clear reasoning for the file operations\r\n\r\n{{ ctx.output_format }}\r\n\"#\r\n}",
    "idea_intent_classifier.baml": "enum Intent {\r\n  DISCUSS      // Q&A, analysis, explanation → routes to PECTExpert\r\n  GENERATE     // Create new content → routes to Brainstormer\r\n  FILE_WRITE   // Save/update files → routes to FileManager\r\n}\r\n\r\nenum ContextType {\r\n  SYSTEM_SPECS\r\n  EXPERIMENT_PLAN\r\n  DATA_SCIENCE_PLAN\r\n  EXISTING_IDEA\r\n}\r\n\r\nclass IntentClassifierOutput {\r\n  intent Intent\r\n  confidence float @description(\"0.0 to 1.0 confidence score\")\r\n\r\n  extracted_context string @description(\"Complete context from conversation for downstream agent\")\r\n  \r\n  // For DISCUSS\r\n  requires_external_docs bool\r\n  \r\n  // For GENERATE\r\n  required_context_types ContextType[]?\r\n  \r\n  // For FILE_WRITE\r\n  content_to_save string?\r\n  target_files string[]?\r\n  operation_type string? @description(\"save_new, update_existing, or auto\")\r\n  \r\n  reasoning string\r\n}\r\n\r\nclass CachedContexts {\r\n  system_specs bool\r\n  experiment_plan bool\r\n  data_science_plan bool\r\n  existing_idea bool\r\n}\r\n\r\nclass ConversationState {\r\n  available_files string[]\r\n  cached_contexts CachedContexts\r\n}\r\n\r\nfunction IntentClassifier(\r\n    user_message: string,\r\n    last_3_messages: ConversationMessage[],\r\n    conversation_state: ConversationState\r\n) -> IntentClassifierOutput {\r\n    client GroqRouter\r\n    prompt #\"\r\nYou are an intent classifier for PECT Assistant. The downstream agent receives NO conversation history, only your output.\r\n\r\nCRITICAL: Extract all relevant context. The next agent is context-blind without you.\r\n\r\nINTENT TYPES:\r\n\r\nDISCUSS - Routes to PECTExpert\r\n- Questions, explanations, analysis, comparisons\r\n- Keywords: what, why, how, explain, analyze, compare, discuss\r\n\r\nRequired extraction:\r\n- extracted_context: All relevant info from conversation (3-10 sentences)\r\n  Include: previous answers, mentioned systems, data, results\r\n  Replace pronouns with explicit nouns (no \"it\", \"this\", \"that\")\r\n- user_request_summary: Restate question with full context\r\n  Example: \"How does photoelectrochemical CO2 reduction work?\" not \"How does this work?\"\r\n- requires_external_docs: true if needs papers/external research\r\n\r\nGENERATE - Routes to Brainstormer\r\n- Create new ideas, plans, experiments, methodologies\r\n- Keywords: generate, create, design, develop, brainstorm, propose, suggest\r\n\r\nRequired extraction:\r\n- extracted_context: Complete background for generation (5-15 sentences)\r\n  Include: what has been discussed, existing work, constraints, goals, technical details\r\n  Pull from cached_contexts if available\r\n- required_context_types: Which cached contexts needed\r\n\r\nFILE_WRITE - Routes to FileManager\r\n- Save, update, modify files\r\n- Keywords: save, update, write, edit, approve\r\n\r\nRequired extraction:\r\n- extracted_context: What is being saved and why (1-2 sentences)\r\n- content_to_save: Actual content to write\r\n- target_files: File names/paths\r\n- operation_type: save_new, update_existing, or auto\r\n\r\nEXTRACTION RULES:\r\n1. Downstream agent sees only your output, nothing else\r\n2. Replace all pronouns with explicit references\r\n3. Include numbers and parameters mentioned\r\n4. Keep technical terms exact\r\n5. Make extracted_context self-contained\r\n6. Focus on relevance, skip irrelevant details\r\n\r\nCONTEXT:\r\n\r\n{% if last_3_messages %}\r\n<recent_conversation>\r\n{% for msg in last_3_messages %}\r\n{{ msg.role }}: {{ msg.content }}\r\n{% endfor %}\r\n</recent_conversation>\r\n{% endif %}\r\n\r\n<conversation_state>\r\nAvailable files: {{ conversation_state.available_files }}\r\n\r\nCached contexts:\r\n- system_specs: {{ \"Yes\" if conversation_state.cached_contexts.system_specs else \"No\" }}\r\n- experiment_plan: {{ \"Yes\" if conversation_state.cached_contexts.experiment_plan else \"No\" }}\r\n- data_science_plan: {{ \"Yes\" if conversation_state.cached_contexts.data_science_plan else \"No\" }}\r\n- existing_ideas: {{ \"Yes\" if conversation_state.cached_contexts.existing_idea else \"No\" }}\r\n</conversation_state>\r\n\r\nUSER MESSAGE: {{ user_message }}\r\n\r\nPROCESS:\r\n1. Analyze user message for intent keywords\r\n2. Extract all relevant context from conversation and cached contexts\r\n3. Restate user request with full context\r\n4. Classify intent with confidence (0.9-1.0 explicit, 0.6-0.8 moderate, 0.4-0.6 ambiguous)\r\n5. Determine additional needs\r\n6. Validate: Is extracted_context self-contained? Does user_request_summary resolve all ambiguity?\r\n\r\n{{ ctx.output_format }}\r\n\"#\r\n}",
    "idea_pect_expert.baml": "function PECTExpert(\r\n    user_message: string,\r\n    relevant_context: string?, // Pre-filtered, can be from conversation\r\n    external_docs: pdf[]? // Only h dif needed\r\n) -> string {\r\n    client GroqRouter\r\n    prompt #\"\r\nYou are PECT Assistant, expert in Pulsed Eddy Current Testing (PECT) research.\r\n\r\nROLE: Discuss, explain, analyze, and critique PECT/NDT concepts, papers, and approaches.\r\n\r\nRESPONSE PATTERNS BY TYPE:\r\n\r\n1. Technical Q&A: Direct answer + underlying physics + practical implications + real-world constraints\r\n\r\n2. Document Analysis: \r\n- Summary of key points\r\n- Methodology assessment\r\n- Strengths and limitations\r\n- Relevance to PECT field\r\n- Practical applications\r\n\r\n3. Evaluation: \r\n- Acknowledge strengths first\r\n- Identify technical issues or gaps\r\n- Discuss assumptions and validity\r\n- Suggest refinements with rationale\r\n\r\n4. Comparison: \r\n- Advantages/disadvantages of each approach\r\n- Context-dependency discussion\r\n- Trade-offs and key considerations\r\n\r\n5. Interpretation: \r\n- Possible explanations grounded in physics\r\n- Reference to PECT theory and principles\r\n- Connection to established knowledge\r\n\r\n6. Elaboration: \r\n- In-depth explanation with examples\r\n- Step-by-step breakdowns when helpful\r\n\r\n7. Unclear Requests: \r\n- Ask specific clarifying questions\r\n- Explain what additional info would help\r\n\r\nGUIDELINES:\r\n- Be specific and honest about limitations\r\n- Request missing information when needed\r\n- Explain \"why\" behind recommendations\r\n- Consider real-world constraints (noise, material properties, sensor limitations)\r\n- Ground discussions in physics and practical experience\r\n- Use technical precision without unnecessary jargon\r\n\r\n{% if relevant_context %}\r\n<relevant_context>\r\n{{ relevant_context }}\r\n</relevant_context>\r\n{% endif %}\r\n\r\n{% if external_docs %}\r\n<external_docs>\r\nEXTERNAL DOCUMENTATION:\r\n{% for doc in external_docs %}\r\nDocument {{ loop.index }}:\r\n{{ doc }}\r\n{% endfor %}\r\n</external_docs>\r\n{% endif %}\r\n\r\nUSER MESSAGE: {{ user_message }}\r\n\r\nProvide a thoughtful, technically grounded response.\r\n\"#\r\n}\r\n\r\ntest PECTExpertTest {\r\n  functions [PECTExpert]\r\n  args {\r\n    user_message \"What is PECT?\"\r\n  }\r\n}",
    "models.baml": "class ConversationMessage {\r\n  role \"user\" | \"assistant\"\r\n  content string\r\n}",
    "reporting_editor.baml": "class EditFileTool {\r\n    tool_name \"edit_file\" @description(\"Use this tool to edit files using an AI-powered code editor\")\r\n    instruction string @description(\"Detailed instruction for the LLM editor on what changes to make\")\r\n    files string[] @description(\"List of file paths to edit\")\r\n}\r\n\r\nfunction ReportingEditor(\r\n  user_message: string,\r\n  conversation_history: ConversationMessage[]?,\r\n  available_files: string[],\r\n) -> EditFileTool {\r\n  client GroqRouter\r\n  prompt #\"\r\nYou are a file editing agent that helps users modify their files using an AI-powered code editor.\r\nYour role is to analyze the user's request and create appropriate editing instructions.\r\n\r\n<task>\r\nBased on the user's message and conversation context, you must:\r\n1. Understand what changes the user wants to make\r\n2. Select which files need to be edited\r\n3. Create a clear, detailed instruction for the LLM editor (aider) to execute the changes\r\n</task>\r\n\r\n<available_files>\r\n{% for file in available_files %}\r\n- {{ file }}\r\n{% endfor %}\r\n</available_files>\r\n\r\n<file_selection_guidelines>\r\n- Choose files that are relevant to the user's requested changes\r\n- You can select multiple files if the changes span across them\r\n- Consider dependencies between files (e.g., if changing a function, include files that call it)\r\n- If the user mentions specific files, prioritize those\r\n- If no files are mentioned, infer from the context and available files\r\n</file_selection_guidelines>\r\n\r\n<instruction_creation_guidelines>\r\nCreate clear, actionable instructions for the LLM editor (aider). Your instruction should:\r\n\r\n1. BE SPECIFIC AND DETAILED: Don't just say \"fix the bug\" - explain what needs to be fixed and how\r\n2. INCLUDE CONTEXT: Explain why the change is needed if relevant\r\n3. SPECIFY THE SCOPE: Clearly state what should and shouldn't be changed\r\n4. PROVIDE EXAMPLES: If applicable, show before/after examples or specific code patterns\r\n5. PRESERVE EXISTING FUNCTIONALITY: Remind to maintain backward compatibility if needed\r\n\r\nGOOD INSTRUCTION EXAMPLES:\r\n- \"Refactor the `process_data` function to use async/await instead of callbacks. Keep the same function signature and return type.\"\r\n- \"Add error handling to the file upload function. Wrap the file operations in try-catch blocks and return appropriate error messages.\"\r\n- \"Update the API endpoint from `/api/v1/users` to `/api/v2/users` and add pagination support with `page` and `limit` query parameters.\"\r\n\r\nBAD INSTRUCTION EXAMPLES:\r\n- \"Make it better\" (too vague)\r\n- \"Fix\" (no context on what to fix)\r\n- \"Update the code\" (no specific direction)\r\n</instruction_creation_guidelines>\r\n\r\n<conversation_context>\r\n{% if conversation_history %}\r\nRECENT CONVERSATION:\r\n{% for msg in conversation_history %}\r\n{{ msg.role }}: {{ msg.content }}\r\n{% endfor %}\r\n{% endif %}\r\n</conversation_context>\r\n\r\n<current_request>\r\nUSER REQUEST: {{ user_message }}\r\n</current_request>\r\n\r\n<instructions>\r\n1. Analyze the user_message to understand what edits are needed\r\n2. Review conversation_history for additional context about the changes\r\n3. Select the appropriate files from available_files that need to be edited\r\n4. Create a detailed, specific instruction that the aider tool can execute\r\n5. Return EditFile with the instruction and list of file paths\r\n\r\nThe instruction should be written as if you're talking directly to an AI code editor that will make the changes.\r\nBe specific, clear, and include all necessary details for the editor to complete the task successfully.\r\n</instructions>\r\n\r\nGenerate the editing instruction and select the files to edit.\r\n{{ ctx.output_format }}\r\n\"#\r\n}\r\n\r\ntest ReportingEditorTest {\r\n  functions [ReportingEditor]\r\n  args {\r\n    user_message \"Add a risk assessment section to the experiment plan\"\r\n    conversation_history [\r\n      {\r\n        role \"user\"\r\n        content \"I think we should add a section discussing potential risks in the experiment\"\r\n      }\r\n      {\r\n        role \"assistant\"\r\n        content \"Good idea. I can add a risk assessment section covering equipment failure, sample contamination, and measurement errors\"\r\n      }\r\n    ]\r\n    available_files [\"plans/crack_detection_experiment.md\", \"plans/corrosion_study.md\"]\r\n  }\r\n}\r\n\r\n\r\n\r\n",
    "tools.baml": "class ToolResult {\r\n    name string\r\n    success bool\r\n    output string | map<string, string>?\r\n    error string?\r\n}",
}

def get_baml_files():
    return _file_map